export const ACTIVE_TEMPLATES=TEMPLATES.filter(t=>t.active);
export const ACTIVE_THEME_IDS=ACTIVE_TEMPLATES.map(t=>t.id);
export const IMMERSIVE_THEME_IDS=ACTIVE_TEMPLATES.filter(t=>t.engine!==null).map(t=>t.id);
const byId=new Map(TEMPLATES.flatMap(t=>[[t.id,t],...(t.aliases||[]).map(a=>[a,t])]));
export const getTemplate=id=>byId.get(id)||null;
export const isImmersiveTemplate=id=>Boolean(getTemplate(id)?.active&&getTemplate(id)?.engine);
export const normalizeThemeId=id=>{const t=getTemplate(id);return t?.active?t.id:FALLBACK_THEME_ID};
